contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 callValue) public payable {
        require(callValue == 0, "no ether needed");
        uint256 valueBefore = c.value(); if (__ESBMC_reverted()) return;
        uint256 remainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklisted = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 balanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 remainingAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;

        uint256 expected = valueBefore <= remainingBefore ? valueBefore : remainingBefore;
        assert(blacklisted || reverted ? (balanceAfter == balanceBefore && remainingAfter == remainingBefore) : (balanceAfter == balanceBefore + expected && remainingAfter == remainingBefore - expected));
    }

    receive() external payable {}
}

